WITH RECURSIVE x7 AS (SELECT X() FROM x11) SELECT x5.x1.x5 - INTERVAL '1' HOUR, x5.x1.x3 + INTERVAL '1.1' SECOND, AVG(x5.x1.x5 - INTERVAL '1' HOUR) AS x3, x5.x1.x4 - INTERVAL '1' SECOND FROM v40543 AS x5 WHERE EXISTS(SELECT x5.x1.x3 + INTERVAL '1.1' SECOND, x5.x1.x5 - INTERVAL '1.1' SECOND, SUM(x5.x1.x5 + INTERVAL '1' HOUR) FROM x10 AS x15 WHERE x5.x1.x5 + INTERVAL '1' HOUR = x5.x1.x5 + INTERVAL '1' HOUR GROUP BY x5.x1.x3 + INTERVAL '1.1' SECOND, x5.x1.v40526 + INTERVAL '1' SECOND WITH ROLLUP HAVING SUM(x5.x1.x5 + INTERVAL '1' HOUR) > 40 ORDER BY x5.x1.x5 - INTERVAL '1' HOUR, x5.x1.x5 - INTERVAL '1' HOUR)